(()=>{
'use strict';
const dialog=$('photoSearchDialog'),input=$('watchPhotoFile'),preview=$('watchPhotoPreview'),run=$('runPhotoSearch'),message=$('photoSearchMessage');let selected=null,objectUrl='',token=0,indexPromise;
const t=s=>window.JXI18n?.translate(s)||s;
function status(text){message.textContent=text;}
function resetBusy(){run.disabled=!selected;run.textContent='Find similar watches';run.removeAttribute('aria-busy');}
$('openPhotoSearch').onclick=()=>{status(selected?'Ready to compare your photo.':'First use may take a moment.');resetBusy();dialog.showModal()};
$('chooseWatchPhoto').onclick=()=>input.click();
input.addEventListener('change',async()=>{const file=input.files?.[0];if(!file)return;const request=++token;selected=null;resetBusy();preview.hidden=true;if(file.size>12*1024*1024){status('Choose an image smaller than 12 MB.');input.value='';return}if(!file.type.startsWith('image/')&&!/\.(jpe?g|png|webp|gif|bmp|avif|heic|heif)$/i.test(file.name)){status('Please choose an image file.');input.value='';return}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);try{const image=new Image();image.src=objectUrl;await image.decode();if(request!==token)return;if(image.naturalWidth<64||image.naturalHeight<64)throw Error('small');selected=image;preview.src=objectUrl;preview.hidden=false;status('Ready to compare your photo.');resetBusy()}catch{if(request===token){status('This image cannot be opened. Try a JPG or PNG.');input.value='';selected=null;resetBusy()}}});
async function deadline(promise){let timer;try{return await Promise.race([promise,new Promise((_,reject)=>{timer=setTimeout(()=>reject(Error('Timeout')),60000)})])}finally{clearTimeout(timer)}}
async function index(){if(!indexPromise)indexPromise=fetch('visual-index-20261114.json?v=1').then(r=>{if(!r.ok)throw Error('Index unavailable');return r.json()}).then(data=>data.rows.map(row=>({...row,features:row.vectors.map(JXVision.unpack)}))).catch(e=>{indexPromise=null;throw e});return indexPromise;}
run.onclick=async()=>{if(!selected)return;const request=++token;run.disabled=true;run.setAttribute('aria-busy','true');status('Loading image matcher…');try{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));const [rows]=await deadline(Promise.all([index(),JXVision.load()]));if(request!==token)return;status('Comparing watches…');const query=await JXVision.extract(selected);if(request!==token)return;const available=new Set(catalogEntries.map(e=>e.code));const ranked=rows.map(row=>({code:row.id+'-'+row.color,score:JXVision.similarity(query,row.features)})).filter(row=>available.has(row.code)).sort((a,b)=>b.score-a.score).slice(0,24);if(!ranked.length||ranked[0].score<.62){status('No close visual matches found. Try a clearer front-facing photo.');resetBusy();return}photoMatches=new Map(ranked.map(row=>[row.code,row.score]));activeBrand=activeSeries=activeBand=activeColor='All';searchTerm='';currentPage=1;syncControls();$('photoQueryPreview').src=selected.src;$('photoResults').hidden=false;render();updateUrl();resetBusy();dialog.close();$('collection').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});}catch(error){if(request!==token)return;status('Image search is unavailable. Please retry.');resetBusy()}};
dialog.addEventListener('close',()=>{token++;resetBusy()});
$('clearPhotoResults').onclick=()=>{clearPhotoResults();currentPage=1;render();updateUrl()};
$('floatingSearch').onclick=()=>{const search=$('catalogSearch');search.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});$('productSearch').focus({preventScroll:true})};
window.JXPhotoSearch={get active(){return !!photoMatches},clear:clearPhotoResults};
})();
